mapper.select:
SELECT 
  FROM act01_account_code a
 WHERE a.act01_company_id                   = #{companyId}
   AND COALESCE(a.act01_use_yn, 'false')    LIKE #{useYn}
   AND COALESCE(a.act01_attribute_cd, '%')  LIKE #{attributeCode}
   AND a.act01_account_cd || a.act01_account_nm || COALESCE(a.act01_account_nm2, '') || COALESCE(a.act01_account_enm, '') LIKE #{searchText}
 ORDER BY a.act01_print_seq

SELECT 
  FROM act01_account_code a
 WHERE a.act01_account_code_id = #{accountCodeId}

mapper.update:
UPDATE act01_account_code
   SET act01_account_nm2 = #{req.accountName2},
       act01_print_yn    = #{req.printYn},
       act01_use_yn      = #{req.useYn}
 WHERE act01_account_code_id = #{req.accountCodeId}
   AND act01_company_id      = #{companyId}

mapper.delete:
DELETE FROM act01_account_code
 WHERE act01_company_id = #{companyId}
   AND act01_account_code_id IN
#{id}

