mapper.update:
UPDATE act01_account_code
   SET act01_account_nm     = #{std.accountName}
     , act01_account_nm2    = #{std.accountName2}
     , act01_account_enm    = #{std.accountEName}
     , act01_parent_cd      = #{std.parentCode}
     , act01_attribute_cd   = #{std.attributeCode}
     , act01_drcr_type      = #{std.drcrType}
     , act01_slip_yn        = #{std.slipYn}
     , act01_use_yn         = #{std.useYn}
     , act01_content        = #{std.content}
     , act01_fss_yn         = #{std.fssYn}
     , act01_fss_account_nm = #{std.fssAccountName}
     , act01_fss_slip_yn    = #{std.fssSlipYn}
     , act01_print_yn       = #{std.printYn}
     , act01_print_seq      = NULL
 WHERE act01_company_id = #{companyId}
   AND act01_account_cd = #{std.accountCode}
